#!/usr/bin/env python3
"""
Round nh1 (culprits-tiles-more), 16 October 2026: the data for the Invasion
of non-humans map (maps repo invasion-of-nonhumans.html, and the Culprits row
nonhuman_atlas). From the Invasion of non-humans chat; needs no other round.

New files only, nothing existing is changed; everything they make goes under
nonhuman/, a folder no other script writes:
  scripts/lib/nhcommon.py        shared helpers (country names, tenths, stamps)
  scripts/nonhuman_griis.py      introduced and invasive species per country (GRIIS on GBIF), weekly
  scripts/nonhuman_firsts.py     first records of alien species (Seebens et al., Zenodo), weekly
  scripts/nonhuman_invacost.py   costs of invasive species per country and year (InvaCost), weekly
  scripts/nonhuman_faostat.py    pesticide use and trade per country (FAOSTAT), weekly
  scripts/nonhuman_pestco.py     the largest pesticide companies and what they own (Wikidata), weekly
  scripts/nonhuman_pestrisk.py   pesticide pollution risk (Tang et al. 2021, figshare), once
  scripts/nonhuman_pestgrids.py  pesticides by active ingredient (PEST-CHEMGRIDS, Earthdata login), once
  scripts/nonhuman_paddd.py      PADDD events (PADDDtracker v2.1, Zenodo), once
  scripts/nonhuman_extraction.py mines by distance from protected areas (mines file, WDPA), monthly
  scripts/nonhuman_anthromes.py  anthromes 10,000 BCE to 2017 (Ellis et al., Dataverse), once

Afterwards: Actions > refresh > Run workflow with
  nonhuman_griis nonhuman_firsts nonhuman_invacost nonhuman_faostat nonhuman_pestco nonhuman_pestrisk nonhuman_paddd nonhuman_anthromes
and then, on their own (each is long):
  nonhuman_pestgrids
  nonhuman_extraction
Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/lib/nhcommon.py': '', 'scripts/nonhuman_anthromes.py': '', 'scripts/nonhuman_extraction.py': '', 'scripts/nonhuman_faostat.py': '', 'scripts/nonhuman_firsts.py': '', 'scripts/nonhuman_griis.py': '', 'scripts/nonhuman_invacost.py': '', 'scripts/nonhuman_paddd.py': '', 'scripts/nonhuman_pestco.py': '', 'scripts/nonhuman_pestgrids.py': '', 'scripts/nonhuman_pestrisk.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("nonhuman1_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"nonhuman1_tiles: wrote {path}")
    if not changed:
        print("nonhuman1_tiles: already applied")


if __name__ == "__main__":
    main()
